# Let's get phone numbers for each friend from the contacts list.
# We'll search contacts for each friend name to find their phone numbers.
friends = ["Cody", "Robin", "Brenda", "James", "Erica", "Nancy", "Chris", "Katie", "Anita", "Paul"]
phone_token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJwaG9uZSs1NDEyNTY0NTMyIiwiZXhwIjoxNjg0NDEyNzQxfQ.OrTdbUe-RXTvkflntrRFqJcVVEb2t9j_Dn8ndjBw9uk"

# We'll search contacts for each friend and collect their phone numbers.
friend_phones = {}
for name in friends:
    result = apis.phone.search_contacts(access_token=phone_token, query=name, page_limit=20)
    # The result may be a list of contacts; we'll find the one matching the first name.
    # We'll just take the first contact that matches the name.
    if isinstance(result, list):
        for contact in result:
            if contact.get("first_name", "").lower() == name.lower():
                friend_phones[name] = contact.get("phone_number")
                break
    else:
        print(f"Error for {name}: {result}")
print(friend_phones)

